/*
 * A041894  Numerators of continued fraction convergents to sqrt(469).
 * https://oeis.org/A041894
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy, less
 * Formula:   a(n) = numerator of the n-th convergent of the continued
 *            fraction of sqrt(469). The recurrence is p_{-2} = 0, p_{-1} = 1,
 *            p_k = a_k * p_{k-1} + p_{k-2} with a_0 = ⌊√469⌋ = 21 and the
 *            finite-periodic sequence (a_k) generated by the standard
 *            continued‑fraction algorithm for √469
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 34, u128 n <= 69,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Static cache of computed numerators */
    static seq_t *cache      = NULL;
    static size_t cache_cap  = 0;
    static idx_t  last_idx   = (idx_t)-1;  /* no values computed yet */

    /* Variables that keep the state of the continued‑fraction and
       the recurrence between calls.  They are initialised lazily. */
    static uint64_t m = 0, d = 1, a_cur = 21, a0 = 21;
    static seq_t   prev2 = 1, prev1 = 21;   /* prev2 = p_{-1} = 1,
                                               prev1 = p_0     = 21   */
    static seq_t   p_curr = 21;             /* current convergent numerator */
    static int     initialized = 0;

    /* Ensure the cache is large enough. */
    if (n + 1 > cache_cap) {
        size_t new_cap = cache_cap > 0 ? cache_cap : 64;
        while (new_cap <= n) new_cap <<= 1;
        cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }

    /* First run – initialise the state. */
    if (!initialized) {
        /* a0 = floor(sqrt(469)) = 21 is already in a_cur. */
        cache[0] = p_curr;      /* a(0) = 21 */
        last_idx = 0;

        /* Compute the first period step (k = 1). */
        uint64_t m1 = d * a_cur - m;                         /* = 21          */
        uint64_t d1 = (469 - m1 * m1) / d;                   /* = 28          */
        uint64_t a1 = (a0 + m1) / d1;                       /* = 1           */

        /* Update the state for the next iteration (k = 1). */
        m   = m1;
        d   = d1;
        a_cur = a1;        /* a_1 = 1                       */

        /* For the recurrence we need p_{-1} and p_0:
           prev2 = p_{-1} = 1,  prev1 = p_0 = 21  */
        prev2 = 1;
        prev1 = 21;

        initialized = 1;
    }

    /* If the requested index is already in the cache, return it. */
    if (n <= last_idx)
        return cache[n];

    /* Compute the remaining terms up to n. */
    for (idx_t i = last_idx + 1; i <= n; ++i)
    {
        /* Compute the next numerator p_i. */
        p_curr = (seq_t)a_cur * prev1 + prev2;
        cache[i] = p_curr;

        /* Shift the recurrence variables. */
        prev2 = prev1;
        prev1 = p_curr;

        /* Advance the continued‑fraction numbers. */
        uint64_t m_next = d * a_cur - m;
        uint64_t d_next = (469 - m_next * m_next) / d;
        uint64_t a_next = (a0 + m_next) / d_next;

        m = m_next;
        d = d_next;
        a_cur = a_next;
    }

    last_idx = n;
    return cache[n];
}
